    fx = r.get("fx_1y") or {}; rp, ma, dd, lc = fx.get("range_pos_pct"), fx.get("vs_ma200_pct"), fx.get("max_dd_pct"), r["lc_dist_pct"]
    a = (2 if rp <= 40 else 1 if rp <= 70 else 0) if isn(rp) else None
