    nz = lambda x, f: f(x) if isn(x) else None
    pts = {"swap": 4 if y >= 6 else 3 if y >= 4 else 2 if y >= 2.5 else 1 if y >= 1 else 0,
           "price": None if a is None and b is None else (a or 0) + (b or 0),
           "direction": nz(r.get("direction"), lambda x: int(x >= 0)), "swap_trend": nz(r.get("swap_change_pct"), lambda x: int(x >= -10)),
           "drawdown": nz(dd, lambda x: int(x <= lc / 2)), "total_1y": nz(r.get("total_1y_lev1_pct"), lambda x: int(x > 0))}
    tot = sum(v for v in pts.values() if isn(v))
    g = g0 = "A" if tot >= 9 else "B" if tot >= 6 else "C"; F = []; dn = {"A": "B", "B": "C", "C": "C"}
    if g == "A" and not (pts["swap"] >= 2 and (pts["price"] or 0) >= 2): g = "B"; F.append("A条件（スワップ点2以上かつ価格水準点2以上）を満たさずBまで")
    if g == "A" and isn(dd) and dd > lc: g = "B"; F.append(f"1年最大DD {dd}% がレバ{cfg['score_leverage']}倍のロスカット距離 {lc}% 超でBまで")
    if y <= 0: g = "C"; F.append("買いスワップがマイナス")
    if isn(r.get("days_to_cb")) and r["days_to_cb"] <= 7: g = dn[g]; F.append(f"中銀会合まで{r['days_to_cb']}日：新規は会合後に（1段階下げ）")
    if r.get("key_3d"): F.append("重要指標まで3日以内（新規は通過後に）: " + " / ".join(r["key_3d"]))
    for e in r.get("recent", []):
        if e["effect"] == "adverse": g = dn[g]; F.append(f"{e['name']}: 買いに不利なサプライズ（1段階下げ）")
        elif e["effect"] == "favorable": F.append(f"{e['name']}: 買いに有利なサプライズ（点数は変えない）")
        else: F.append(f"{e['name']}: 通過（事前の注意は解除）。" + ("サプライズなし" if e["surprise"] == "no" else "サプライズ判定は不明"))
    return {"score": tot, "points": pts, "grade_raw": g0, "grade": g, "flags": F}

def positions(pos, q, evr, t, cfg):
    X = [x for x in pos.get("positions", []) if x.get("pair") and x.get("units")]; eq = pos.get("equity_jpy"); out = {"positions": [], "account": {}}
    if not X: return out
    mid = lambda p: (q[p]["bid"] + q[p]["ask"]) / 2 if p in q else None
    def ntl(x):
        b, c = bq(x["pair"]); px = (mid(x["pair"]) or x["entry_price"]) if c == "JPY" else mid(b + "JPY")
        return x["units"] * px if px else None
    N = [ntl(x) for x in X]; tot = sum(N) if all(N) else None; m, lv, cap = cfg["margin_rate"], cfg["losscut_level"], cfg["leverage_cap"]
    acc = {"equity_jpy": eq, "notional_jpy": round(tot) if tot else NA, "leverage_cap": cap}
    if tot and eq:
        acc.update(leverage=round(tot / eq, 2), cap_ok=tot / eq <= cap, room_at_cap_jpy=round(eq * cap - tot), margin_ratio_pct=round(eq / (tot * m) * 100, 1))
        if isn(cfg.get("max_extra_deposit_jpy")): acc["room_with_max_deposit_jpy"] = round((eq + cfg["max_extra_deposit_jpy"]) * cap - tot)
    out["account"] = acc
