        p = x["pair"]; b, c = bq(p); side = x.get("side", "buy"); qq = q.get(p, {}); bid = qq.get("bid")
        r = {**{k: x.get(k) for k in ("pair", "side", "units", "entry_price")}, "bid_now": bid or NA, "bid_time": qq.get("time", NA), "events": []}
        if c != "JPY" or not isn(eq): r["losscut_price"] = "算出せず（対円以外か純資産が未入力）"; out["positions"].append(r); continue
        ref = x.get("ref_price") or (pos.get("equity_ref_price") if len(X) == 1 else None) or x["entry_price"]
        mo = sum(N[j] or 0 for j in range(len(X)) if j != i) * m * lv; u = x["units"]
        lcp = (u * ref - eq + mo) / (u * (1 - m * lv)) if side == "buy" else (eq + u * ref - mo) / (u * (1 + m * lv))
        r["losscut_price"] = round(lcp, 4)
        r["basis"] = f"純資産 {eq}円を価格 {ref} 時点とみなし、追加入金なし・維持率{lv * 100:.0f}%・必要証拠金率{m * 100:g}%で計算" + ("（他の保有は今の値のまま）" if len(X) > 1 else "")
        if bid: r["losscut_dist_pct"] = round((1 - lcp / bid) * 100 * (1 if side == "buy" else -1), 2)
        for e in recent(evr, (b, c), t):
            mv = next((k for k in e.get("price_moves", []) if k["pair"] == p), {})
            z = {"name": e.get("name"), "surprise": e.get("surprise"), "effect": effect_on_buy(e, p), "move_pct": mv.get("change_pct", NA)}
            if isn(mv.get("before")): z["lc"] = f"{(1 - lcp / mv['before']) * 100:.2f}% → {(1 - lcp / mv['after']) * 100:.2f}%"
            r["events"].append(z)
        out["positions"].append(r)
    return out

